import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# 1️⃣  Custom CUDA kernel & host wrapper for elementwise addition (+)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b)"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


# ----------------------------------------------------------------------
# 2️⃣  Custom CUDA kernel & host wrapper for argmax along a dimension
# ----------------------------------------------------------------------
argmax_cuda_cpp_source = (
    "torch::Tensor argmax_cuda(torch::Tensor x, int dim)"
)

argmax_kernel_source = """
__global__ void argmax_kernel(const float* data, long long* out, int batch, int dim1, int dim2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch * dim1) {
        int b = idx / dim1;
        int d1 = idx % dim1;
        float max_val = -float(\"inf\");
        int max_idx = 0;
        for (int k = 0; k < dim2; ++k) {
            float val = data[b * dim1 * dim2 + d1 * dim2 + k];
            if (val > max_val) {
                max_val = val;
                max_idx = k;
            }
        }
        out[b * dim1 + d1] = static_cast<long long>(max_idx);
    }
}

torch::Tensor argmax_cuda(torch::Tensor x, int dim) {
    assert x.dim() == 3, "argmax_cuda only supports 3‑D tensors."
    batch = x.size(0)
    dim1 = x.size(1)
    dim2 = x.size(2)

    out_shape = list(x.shape)
    out_shape.remove(dim)          # remove the requested dimension
    out = torch.zeros(out_shape, dtype=torch.long, device=x.device)

    const int block_size = 256;
    const int num_blocks = (batch * dim1 + block_size - 1) // block_size;

    argmax_kernel<<<num_blocks, block_size>>>(
        x.data_ptr().const_cast<const float*>(x.data_ptr()),
        out.data_ptr().const_cast<long long*>(out.data_ptr()),
        batch=batch,
        dim1=dim1,
        dim2=dim2
    );

    return out;
}
"""

argmax_cuda = load_inline(
    name="argmax_cuda",
    cpp_sources=argmax_cuda_cpp_source,
    cuda_sources=argmax_kernel_source,
    functions=["argmax_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


# ----------------------------------------------------------------------
# 3️⃣  Optimized model (ModelNew) – replaces the original forward with custom ops
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add   # kept for API compatibility
        self.argmax_cuda = argmax_cuda
        self.dim = 2                              # argmax is performed over the last dimension (dim2)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x: Input tensor of shape (batch, dim1, dim2).
        Returns:
            Tensor of shape (batch, dim1) containing the index of the maximum value along the last dimension.
        """
        return self.argmax_cuda(x, self.dim)
